'use strict';
const activityLabels={expenses:'Expenses & repayments',shopping:'Shopping',chores:'Chores',reminders:'Reminders',calendar:'Calendar',fines:'Fines & fame',flat:'Flatmates'};
const KEY='flatmate-hq-v1',VERSION=1;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const id=()=>crypto.randomUUID();
const today=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Pacific/Auckland',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const dateObj=d=>new Date(d+'T00:00:00Z'),dateAdd=(d,n)=>{const a=dateObj(d);a.setUTCDate(a.getUTCDate()+n);return a.toISOString().slice(0,10)},fmtDate=(d,options={day:'numeric',month:'short'})=>dateObj(d).toLocaleDateString('en-NZ',{...options,timeZone:'UTC'});
const monday=d=>dateAdd(d,-((dateObj(d).getUTCDay()+6)%7));
const money=n=>new Intl.NumberFormat('en-NZ',{style:'currency',currency:'NZD'}).format(n/100);
function cents(value){if(!/^\d+(\.\d{1,2})?$/.test(String(value)))throw Error('Enter a positive amount with no more than two decimal places.');const [a,b='']=String(value).split('.');const c=Number(a)*100+Number(b.padEnd(2,'0'));if(c<=0||c>100000000)throw Error('Enter an amount between $0.01 and $1,000,000.');return c}
function equalShares(amount,people){const base=Math.floor(amount/people.length),extra=amount%people.length;return Object.fromEntries(people.map((p,i)=>[p,base+(i<extra?1:0)]))}
function blank(){return {version:VERSION,name:'Your flat',members:[],expenses:[],payments:[],tasks:[],weeks:{},shopping:[],events:[],reminders:[],activity:[],fines:[],awards:{}}}
let state=blank(),week=monday(today()),month=today().slice(0,7),page='home';
function validate(s){if(!s||s.version!==1||typeof s.name!=='string'||!s.name.trim()||s.name.length>60)throw Error('This file is not a supported Flatmate HQ backup.');for(const k of ['members','expenses','payments','tasks','shopping','events','fines'])if(!Array.isArray(s[k])||s[k].length>10000)throw Error('Invalid backup records.');if(!s.weeks||typeof s.weeks!=='object'||Array.isArray(s.weeks)||!s.awards||typeof s.awards!=='object')throw Error('Invalid weekly records.');if(s.reminders===undefined)s.reminders=[];if(!Array.isArray(s.reminders)||s.reminders.length>10000)throw Error('Invalid reminders.');if(s.activity===undefined)s.activity=[];if(!Array.isArray(s.activity)||s.activity.length>500||s.activity.some(x=>!x||typeof x.id!=='string'||x.id.length>100||typeof x.key!=='string'||x.key.length>250||typeof x.title!=='string'||x.title.length>500||typeof x.detail!=='string'||x.detail.length>1000||!['expenses','shopping','chores','reminders','calendar','fines','flat'].includes(x.category)||typeof x.at!=='string'||!Number.isFinite(Date.parse(x.at))))throw Error('Invalid activity history.');const ids=new Set();const text=(x,max=500)=>typeof x==='string'&&x.length<=max;const date=x=>/^\d{4}-\d{2}-\d{2}$/.test(x)&&!isNaN(+dateObj(x))&&dateObj(x).toISOString().slice(0,10)===x;const amt=x=>Number.isSafeInteger(x)&&x>0&&x<=100000000;
 for(const m of s.members){if(!text(m.id,100)||ids.has(m.id)||!text(m.name,40)||!m.name.trim())throw Error('Invalid flatmate.');ids.add(m.id)}const known=x=>ids.has(x);
 for(const x of s.expenses)if(!text(x.id,100)||!text(x.title,100)||!amt(x.amount)||!known(x.payer)||!date(x.date)||!Array.isArray(x.people)||!x.people.length||new Set(x.people).size!==x.people.length||!x.people.every(known))throw Error('Invalid expense.');
 for(const x of s.expenses)if(x.receipt&&!validReceipt(x.receipt))throw Error('Invalid receipt.');
 for(const x of s.reminders)if(!text(x.id,100)||!text(x.title,100)||!x.title.trim()||!date(x.date)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(x.time)||![0,7,14].includes(x.repeat)||typeof x.done!=='boolean'||!text(x.notes))throw Error('Invalid reminder.');
 for(const x of s.payments)if(!text(x.id,100)||!known(x.from)||!known(x.to)||x.from===x.to||!amt(x.amount)||!date(x.date))throw Error('Invalid repayment.');
 const taskIDs=new Set();for(const x of s.tasks){if(!text(x.id,100)||taskIDs.has(x.id)||!text(x.title,100)||!text(x.notes)||!date(x.starts))throw Error('Invalid chore.');taskIDs.add(x.id)}
 for(const [w,assignments]of Object.entries(s.weeks)){if(!date(w)||!assignments||typeof assignments!=='object')throw Error('Invalid chore week.');for(const [task,a]of Object.entries(assignments))if(!taskIDs.has(task)||!a||!(a.member===null||known(a.member))||typeof a.done!=='boolean')throw Error('Invalid chore assignment.')}
 for(const x of s.shopping)if(!text(x.id,100)||!text(x.title,100)||!text(x.quantity,40)||!(x.by===''||known(x.by))||typeof x.done!=='boolean')throw Error('Invalid shopping item.');
 for(const x of s.events)if(!text(x.id,100)||!text(x.title,100)||!date(x.date)||!text(x.time,5)||(x.time&&!/^([01]\d|2[0-3]):[0-5]\d$/.test(x.time))||!text(x.notes)||!text(x.type,30))throw Error('Invalid event.');
 for(const x of s.fines)if(!text(x.id,100)||!known(x.member)||!text(x.reason,100)||!date(x.date)||!amt(x.amount)||typeof x.paid!=='boolean')throw Error('Invalid fine.');
 for(const [w,x]of Object.entries(s.awards))if(!date(w)||!known(x.member)||!text(x.reason,200))throw Error('Invalid weekly award.');return s}
try{const saved=localStorage.getItem(KEY);if(saved)state=validate(JSON.parse(saved))}catch{setTimeout(()=>toast('Saved data could not be read. Import a backup if you have one.'),300)}
function validReceipt(r){return r&&typeof r.name==='string'&&r.name.length<=200&&typeof r.data==='string'&&r.data.length<=1400000&&/^data:(image\/(png|jpeg|webp)|application\/pdf);base64,[A-Za-z0-9+/=]+$/.test(r.data)}
let activityBefore=structuredClone(state),activityFilter='all';
function save(){const previousLog=state.activity||[];try{state.activity=[...previousLog,...activityChanges(activityBefore,state)].slice(-500);localStorage.setItem(KEY,JSON.stringify(state));activityBefore=structuredClone(state);return true}catch{state.activity=previousLog;toast('Storage is full or unavailable. Export a backup before closing.');return false}}
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
const member=m=>state.members.find(x=>x.id===m)?.name||'Unassigned',initial=m=>member(m).split(/\s+/).map(x=>x[0]).slice(0,2).join('').toUpperCase();
const options=(selected,none=false)=>`${none?'<option value="">Anyone</option>':''}${state.members.map(m=>`<option value="${esc(m.id)}" ${m.id===selected?'selected':''}>${esc(m.name)}</option>`).join('')}`;
function balances(){const b=Object.fromEntries(state.members.map(m=>[m.id,0]));for(const x of state.expenses){b[x.payer]+=x.amount;for(const [p,a]of Object.entries(equalShares(x.amount,x.people)))b[p]-=a}for(const x of state.payments){b[x.from]+=x.amount;b[x.to]-=x.amount}return b}
function settlements(){const b=balances(),owe=Object.entries(b).filter(([,v])=>v<0).map(([m,v])=>({m,v:-v})),receive=Object.entries(b).filter(([,v])=>v>0).map(([m,v])=>({m,v}));const out=[];let i=0,j=0;while(i<owe.length&&j<receive.length){const amount=Math.min(owe[i].v,receive[j].v);out.push({from:owe[i].m,to:receive[j].m,amount});owe[i].v-=amount;receive[j].v-=amount;if(!owe[i].v)i++;if(!receive[j].v)j++}return out}
function ensureWeek(w){if(state.weeks[w])return;const previous=state.weeks[dateAdd(w,-7)]||{};state.weeks[w]={};for(let i=0;i<state.tasks.length;i++){const t=state.tasks[i];if(t.starts>w)continue;const prev=previous[t.id]?.member,prevIndex=state.members.findIndex(m=>m.id===prev);state.weeks[w][t.id]={member:state.members.length?state.members[(prevIndex>=0?prevIndex+1:i)%state.members.length].id:null,done:false}}save()}
const tasksFor=w=>{ensureWeek(w);return state.tasks.filter(t=>t.starts<=w).map(t=>({...t,...state.weeks[w][t.id]}))};
function head(title,sub,action='',label=''){return `<div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div>${action?`<button class="btn primary" data-action="${action}">＋ ${label}</button>`:''}</div>`}
function empty(title,desc,action='',label=''){return `<div class="empty"><div class="empty-icon">◇</div><strong>${title}</strong><p>${desc}</p>${action?`<button class="btn" data-action="${action}">${label}</button>`:''}</div>`}
function panel(title,body,link='',href=''){return `<section class="panel"><div class="panel-head"><h2>${title}</h2>${link?`<a class="btn ghost" href="#${href}">${link} ↗</a>`:''}</div>${body}</section>`}
const expenseRows=items=>items.map(x=>`<div class="list-row"><div class="round">↔</div><div class="grow"><strong>${esc(x.title)}</strong><p>${esc(member(x.payer))} paid · ${fmtDate(x.date)} · split ${x.people.length} ways</p></div><span class="amount">${money(x.amount)}</span></div>`).join('');
const taskRows=items=>items.map(t=>`<div class="list-row ${t.done?'done':''}"><input class="check" type="checkbox" aria-label="Complete ${esc(t.title)}" data-task="${esc(t.id)}" data-week="${esc(monday(today()))}" ${t.done?'checked':''}><div class="grow"><strong>${esc(t.title)}</strong><p>${esc(member(t.member))}</p></div><span class="badge ${t.done?'green':''}">${t.done?'Done':'This week'}</span></div>`).join('');
function home(){const w=monday(today()),tasks=tasksFor(w),need=state.shopping.filter(x=>!x.done),due=settlements(),outstanding=due.reduce((a,x)=>a+x.amount,0),events=state.events.filter(x=>x.date>=today()).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time)),next=events[0];return head('Home sweet organised home.',`${esc(state.name)} · A little less flat admin. A lot more living.`,'expense','Add expense')+(!state.members.length?`<section class="hero"><div><span class="eyebrow">WELCOME TO FLATMATE HQ</span><h2>Your flat. Minus the chaos.</h2><p>Split the bills, share the jobs, and finally remember the toilet paper.</p><button class="btn primary" data-action="setup" style="margin-top:14px">Set up your flat ↗</button></div><div class="hero-graphic" aria-hidden="true"><span class="house">⌂</span><span class="graphic-chip">One roof. All sorted. ✓</span></div></section>`:`<section class="hero"><div><span class="eyebrow">THE HOUSEHOLD CHECK IN</span><h2>${tasks.filter(t=>!t.done).length?`${tasks.filter(t=>!t.done).length} jobs. One team.`:'Looking good, flatmates.'}</h2><p>${need.length?`${need.length} things on the shopping list. `:''}${due.length?`${due.length} suggested repayments to square things up.`:'Shared expenses are all square.'}</p><a class="btn" href="#chores" style="margin-top:12px">See this week’s chores ↗</a></div><div class="hero-graphic" aria-hidden="true"><span class="house">⌂</span><span class="graphic-chip">${state.members.length} under one roof</span></div></section>`)+`<div class="stats"><div class="stat"><div class="stat-top">Unsettled balances<span class="stat-icon">↔</span></div><div class="value">${money(outstanding)}</div><div class="hint">Across all shared expenses</div></div><div class="stat"><div class="stat-top">Chores completed<span class="stat-icon">✓</span></div><div class="value">${tasks.filter(t=>t.done).length}<span class="muted"> / ${tasks.length}</span></div><div class="hint">This week · ${fmtDate(w)}</div></div><div class="stat"><div class="stat-top">Things we need<span class="stat-icon">▤</span></div><div class="value">${need.length}</div><div class="hint">On the shared shopping list</div></div><div class="stat"><div class="stat-top">Next on the calendar<span class="stat-icon">▦</span></div><div class="value" style="font-size:21px">${next?fmtDate(next.date):'Nothing yet'}</div><div class="hint">${next?esc(next.title):'Make a little room for plans'}</div></div></div><div class="grid"><div class="stack">${panel('Recent activity',activityRows(activityItems().slice(0,5)),'View all','activity')}${panel('Recent expenses',state.expenses.length?expenseRows([...state.expenses].reverse().slice(0,4)):empty('No awkward money chats yet','Add a shared purchase and we’ll do the maths.','expense','Add your first expense'),'View all','expenses')}${panel('Reminders',reminderRows(state.reminders.filter(x=>!x.done).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time)).slice(0,3)),'View all','reminders')}${panel('Coming up',events.length?events.slice(0,3).map(x=>`<div class="list-row"><div class="round">${dateObj(x.date).getUTCDate()}</div><div class="grow"><strong>${esc(x.title)}</strong><p>${fmtDate(x.date)} ${x.time?'· '+esc(x.time):'· All day'}</p></div><span class="badge">${esc(x.type)}</span></div>`).join(''):empty('A little breathing room','Inspections, bin days and flat dinners go here.','event','Add an event'),'Calendar','calendar')}</div><div class="stack">${panel('This week’s chores',tasks.length?taskRows(tasks.slice(0,4)):empty('Share the load','Add weekly jobs and we’ll rotate who does them.','task','Add a chore'),'View all','chores')}${panel('The shopping list',need.length?need.slice(0,4).map(x=>`<div class="list-row"><span class="round green">＋</span><div class="grow"><strong>${esc(x.title)}</strong><p>${esc(x.quantity||'As needed')}</p></div></div>`).join(''):empty('No emergency loo roll runs','Keep track of the little things you’re running out of.','item','Add something'),'View list','shopping')}</div></div>`}
function expenses(){const b=balances(),suggestions=settlements();return head('Fair shares. Clear balances.','Add a purchase, split it equally, and see exactly who owes what.','expense','Add expense')+`<div class="grid"><div class="stack">${panel('Shared expenses',state.expenses.length?`<div class="table-wrap"><table><thead><tr><th>Expense</th><th>Paid by</th><th>Split</th><th>Amount</th></tr></thead><tbody>${[...state.expenses].reverse().map(x=>`<tr><td><strong>${esc(x.title)}</strong><p>${fmtDate(x.date)}</p><button class="text-link" data-action="expenseDetail" data-id="${esc(x.id)}">${x.receipt?'Receipt ↗':'Add receipt'}</button></td><td>${esc(member(x.payer))}</td><td><button class="text-link" data-action="expenseDetail" data-id="${esc(x.id)}">${x.people.length} people ↗</button></td><td>${money(x.amount)}</td></tr>`).join('')}</tbody></table></div>`:empty('Start with the next grocery run','Every current flatmate is included by default.','expense','Add expense'))}${panel('Recorded repayments',state.payments.length?state.payments.slice().reverse().map(x=>`<div class="list-row"><span class="round green">✓</span><div class="grow"><strong>${esc(member(x.from))} → ${esc(member(x.to))}</strong><p>${fmtDate(x.date)} · Recorded payment</p></div><span class="amount">${money(x.amount)}</span></div>`).join(''):empty('No repayments recorded','Record transfers after someone has actually paid.'))}</div><div class="stack">${panel('Everyone’s balance',state.members.length?`<div class="panel-body">${state.members.map(m=>`<div class="settlement"><div class="btn-row"><span class="round">${esc(initial(m.id))}</span><strong class="small">${esc(m.name)}</strong></div><div class="amount ${b[m.id]>0?'money-positive':b[m.id]<0?'money-negative':''}">${money(Math.abs(b[m.id]))}<p class="muted small">${b[m.id]>0?'gets back':b[m.id]<0?'owes':'all square'}</p></div></div>`).join('')}<p class="small muted">Positive balances get money back. Negative balances owe. Each split is exact to the cent.</p></div>`:empty('Add your flatmates first','Balances appear once your flat is set up.','setup','Set up flat'))}${panel('Square it up',suggestions.length?`<div class="panel-body">${suggestions.map(x=>`<div class="settlement"><div><strong class="small">${esc(member(x.from))} → ${esc(member(x.to))}</strong><p class="muted small">${money(x.amount)}</p></div><button class="btn" data-action="settle" data-from="${esc(x.from)}" data-to="${esc(x.to)}" data-amount="${x.amount}">Record paid</button></div>`).join('')}<p class="small muted">Suggested transfers simplify the total balances. This app records repayments; it doesn’t move money.</p></div>`:empty('All square','No repayments needed right now.'))}</div></div>`}
function chores(){const tasks=tasksFor(week);return head('Everyone does their bit.','Weekly chores rotate automatically. Shuffle the unfinished jobs whenever you need.','task','Add weekly chore')+`<div class="week-bar"><div class="week-nav"><button class="icon-button" data-action="prevWeek" aria-label="Previous chore week">‹</button><strong>Week of ${fmtDate(week)}</strong><button class="icon-button" data-action="nextWeek" aria-label="Next chore week">›</button></div><div class="btn-row"><button class="btn" data-action="thisWeek">This week</button><button class="btn" data-action="shuffle" ${!tasks.some(t=>!t.done)||!state.members.length?'disabled':''}>⤨ Shuffle assignments</button></div></div>`+(tasks.length?`<div class="chores-grid">${tasks.map(t=>`<article class="chore-card ${t.done?'done':''}"><div class="chore-title"><h3>${esc(t.title)}</h3><input type="checkbox" class="check" aria-label="Complete ${esc(t.title)}" data-task="${esc(t.id)}" data-week="${esc(week)}" ${t.done?'checked':''}></div><p>${esc(t.notes||'Complete once this week.')}</p><div class="assignee"><span class="round">${esc(t.member?initial(t.member):'?')}</span>${esc(member(t.member))}<button class="text-link" style="margin-left:auto" data-action="assign" data-id="${esc(t.id)}">Reassign</button></div></article>`).join('')}</div><p class="small muted" style="margin-top:20px">Completed jobs stay with the person who did them. New weeks start fresh and rotate each job to the next flatmate.</p>`:panel('Your weekly roster',empty('A clean slate','Start with bathrooms, kitchen, bins and vacuuming.','task','Add a weekly chore')))}
function shopping(){const open=state.shopping.filter(x=>!x.done),done=state.shopping.filter(x=>x.done);const rows=items=>items.map(x=>`<div class="list-row ${x.done?'done':''}"><input class="check" type="checkbox" aria-label="Bought ${esc(x.title)}" data-item="${esc(x.id)}" ${x.done?'checked':''}><div class="grow"><strong>${esc(x.title)}</strong><p>${esc(x.quantity||'As needed')}${x.by?' · Added by '+esc(member(x.by)):''}</p></div><span class="badge ${x.done?'green':'orange'}">${x.done?'Bought':'Need'}</span></div>`).join('');return head('Never out of toilet paper.','One shopping list for the things everyone needs. Tick them off when bought.','item','Add item')+`<div class="grid"><div class="stack">${panel(`We need these <span class="badge orange">${open.length}</span>`,open.length?rows(open):empty('The cupboards are covered','Add toilet paper, dish liquid, milk or whatever’s running low.','item','Add an item'))}${panel('Recently bought',done.length?rows(done.slice().reverse()):empty('Nothing ticked off yet','Bought items will stay here so you can untick them later.'))}</div>${panel('A quick reminder',`<div class="panel-body"><h3>Shopping and expenses are separate.</h3><p class="muted small">After someone buys the shared supplies, add the receipt as an expense to split the cost.</p><button class="btn primary" data-action="expense" style="margin-top:12px">＋ Add shared expense</button></div>`)}</div>`}
function calendar(){const first=month+'-01',count=new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5)),0)).getUTCDate(),offset=(dateObj(first).getUTCDay()+6)%7;const events=state.events.filter(x=>x.date.slice(0,7)===month).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time));return head('Same roof. Same page.','Bin days, inspections, bills and the next flat dinner.','event','Add event')+`<div class="week-bar"><div class="week-nav"><button class="icon-button" data-action="prevMonth" aria-label="Previous month">‹</button><strong>${fmtDate(first,{month:'long',year:'numeric'})}</strong><button class="icon-button" data-action="nextMonth" aria-label="Next month">›</button></div><button class="btn" data-action="currentMonth">This month</button></div><section class="panel"><div class="calendar">${['Mon','Tue','Wed','Thu','Fri','Sat','Sun'].map(d=>`<div class="cal-label">${d}</div>`).join('')}${Array.from({length:offset},()=>'<div class="cal-day blank"></div>').join('')}${Array.from({length:count},(_,i)=>{const d=month+'-'+String(i+1).padStart(2,'0'),dayEvents=events.filter(x=>x.date===d);return `<button class="cal-day ${d===today()?'today':''}" data-action="day" data-date="${d}" aria-label="${fmtDate(d,{weekday:'long',day:'numeric',month:'long'})}, ${dayEvents.length} events"><time>${i+1}</time>${dayEvents.slice(0,2).map(x=>`<span class="cal-event">${esc(x.title)}</span>`).join('')}${dayEvents.length>2?`<span class="cal-event">+${dayEvents.length-2} more</span>`:''}</button>`}).join('')}</div></section><div style="margin-top:22px">${panel('This month’s events',events.length?events.map(x=>`<div class="list-row"><div class="round">${dateObj(x.date).getUTCDate()}</div><div class="grow"><strong>${esc(x.title)}</strong><p>${fmtDate(x.date)} · ${x.time?esc(x.time):'All day'} · ${esc(x.type)}</p>${x.notes?`<p class="notes">${esc(x.notes)}</p>`:''}</div><button class="text-link" data-action="eventDetail" data-id="${esc(x.id)}">View</button></div>`).join(''):empty('Nothing on the calendar','Click a date to add something.'))}</div>`}
function fines(){const award=state.awards[week],unpaid=state.fines.filter(x=>!x.paid),total=unpaid.reduce((a,x)=>a+x.amount,0);return head('House rules. Mild consequences.','Keep flat fines clear, and crown your weekly household menace.','fine','Add fine')+`<div class="week-bar"><div class="week-nav"><button class="icon-button" data-action="prevWeek" aria-label="Previous award week">‹</button><strong>Week of ${fmtDate(week)}</strong><button class="icon-button" data-action="nextWeek" aria-label="Next award week">›</button></div><button class="btn" data-action="thisWeek">This week</button></div><section class="award"><span class="award-icon" aria-hidden="true">♛</span><div class="grow"><span class="eyebrow">ASSHOLE OF THE WEEK</span><h2>${award?esc(member(award.member)):'The crown is unclaimed.'}</h2><p>${award?esc(award.reason):'Choose the winner together, then record the verdict.'}</p></div><button class="btn" data-action="award">${award?'Change winner':'Award the crown'}</button></section><div class="grid"><div>${panel('Flat fine register',state.fines.length?`<div class="table-wrap"><table><thead><tr><th>Flatmate and reason</th><th>Fine</th><th>Status</th></tr></thead><tbody>${state.fines.slice().reverse().map(x=>`<tr><td><strong>${esc(member(x.member))}</strong><p>${esc(x.reason)} · ${fmtDate(x.date)}</p></td><td>${money(x.amount)}</td><td><button class="btn" data-action="finePaid" data-id="${esc(x.id)}">${x.paid?'✓ Paid · undo':'Mark paid'}</button></td></tr>`).join('')}</tbody></table></div>`:empty('No fines. Impressive.','Record the fine after the flat has agreed on it.','fine','Add fine'))}</div><div class="stack">${panel('The flat kitty',`<div class="panel-body"><p class="muted small">Outstanding fines</p><div style="font:750 30px Manrope">${money(total)}</div><p class="muted small">${unpaid.length} unpaid ${unpaid.length===1?'fine':'fines'} · separate from shared expenses</p>${state.members.map(m=>{const due=unpaid.filter(x=>x.member===m.id).reduce((a,x)=>a+x.amount,0);return due?`<div class="settlement"><strong class="small">${esc(m.name)}</strong><span>${money(due)}</span></div>`:''}).join('')}<p class="small muted" style="margin-top:20px">Mark paid when money reaches your agreed flat kitty. No payment is collected through this site.</p></div>`)}${panel('Keep it a flat decision',`<div class="panel-body"><p class="small muted">Agree on house rules, fines and the weekly winner together. The crown doesn’t automatically create a fine.</p></div>`)}</div></div>`}
function render(){const names={home:'Overview',expenses:'Expenses',chores:'Weekly chores',shopping:'Shopping list',calendar:'Calendar',fines:'Fines & fame',reminders:'Reminders',activity:'Activity'};page=location.hash.slice(1)||'home';if(!names[page])page='home';$('#flatName').textContent=state.name;$('#breadcrumb').textContent=state.name+' / '+names[page];$('#topDate').textContent=fmtDate(today(),{weekday:'short',day:'numeric',month:'long'});$$('nav a').forEach(a=>a.classList.toggle('active',a.dataset.page===page));$('#app').innerHTML=({home,expenses,chores,shopping,calendar,fines,reminders,activity}[page])()}
function show(title,body){$('#modalTitle').textContent=title;$('#modalBody').innerHTML=body;if(!$('#modal').open)$('#modal').showModal()}
function close(){ $('#modal').close() }
function form(content,submit,label='Save'){show(submit.title||'Save',`<form id="activeForm">${content}<p class="form-error" role="alert"></p><div class="form-actions"><button type="button" class="btn" data-action="close">Cancel</button><button class="btn primary" type="submit">${label}</button></div></form>`);$('#activeForm').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;const before=structuredClone(state);try{await submit(new FormData(e.target));if(!save())throw Error('Could not save. Free browser storage or use a smaller receipt.');close();render()}catch(err){state=before;$('.form-error').textContent=err.message}finally{button.disabled=false}}}
function openForm(title,content,fn,label='Save'){fn.title=title;form(content,fn,label)}
const field=(label,name,type='text',value='',extras='')=>`<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extras}></label>`;
const select=(label,name,content)=>`<label class="field">${label}<select name="${name}" required>${content}</select></label>`;
const notes=(label='Notes',name='notes',value='')=>`<label class="field">${label}<textarea name="${name}" maxlength="500">${esc(value)}</textarea></label>`;
function needMembers(){if(state.members.length)return true;setup();return false}
function setup(){openForm('Set up your flat',field('Flat name','name','text',state.name==='Your flat'?'':state.name,'required maxlength="60" placeholder="e.g. The Rimu Street Flat"')+field('Flatmates','members','text','','required maxlength="400" placeholder="Benjamin, Sam, Alex, Jamie"')+'<p class="small muted">Separate names with commas. You can add more people later.</p>',f=>{const names=String(f.get('members')).split(',').map(x=>x.trim()).filter(Boolean);if(!names.length||names.length>20)throw Error('Add between 1 and 20 flatmates.');if(names.some(n=>n.length>40)||new Set(names.map(n=>n.toLowerCase())).size!==names.length)throw Error('Use distinct names, up to 40 characters each.');state.name=String(f.get('name')).trim();if(!state.name)throw Error('Add a flat name.');state.members.push(...names.map(name=>({id:id(),name})));for(const [w,a]of Object.entries(state.weeks))for(const t of Object.values(a))if(!t.member)t.member=state.members[0].id;toast('Your flat is ready.')},'Create flat')}
function addExpense(){if(!needMembers())return;openForm('Add shared expense',field('What was it for?','title','text','','required maxlength="100" placeholder="e.g. Weekly groceries"')+`<div class="fields">${field('Total amount NZD','amount','number','','required min="0.01" max="1000000" step="0.01" placeholder="0.00"')}${field('Date','date','date',today(),'required')}</div>`+select('Who paid?','payer',options())+'<p class="small"><strong>Split equally between</strong></p><div class="checks">'+state.members.map(m=>`<label><input type="checkbox" name="people" value="${esc(m.id)}" checked>${esc(m.name)}</label>`).join('')+'</div>'+receiptField()+'<p class="inline-note">All current flatmates are selected. Any leftover cent goes to the first selected flatmate(s), so the split always adds up.</p>',async f=>{const receipt=await readReceipt(f.get('receipt'));const people=f.getAll('people');if(!people.length)throw Error('Choose at least one person to split with.');const title=String(f.get('title')).trim();if(!title)throw Error('Add a description.');state.expenses.push({id:id(),title,amount:cents(f.get('amount')),date:f.get('date'),payer:f.get('payer'),people,receipt});toast('Expense added and split equally.')},'Add expense')}
function expenseDetail(x){const shares=equalShares(x.amount,x.people);show(x.title,`<p class="muted small">${esc(member(x.payer))} paid ${money(x.amount)} · ${fmtDate(x.date)}</p>${Object.entries(shares).map(([p,a])=>`<div class="settlement"><strong>${esc(member(p))}</strong><span>${money(a)}</span></div>`).join('')}<p class="inline-note">Participants are fixed when an expense is added. Adding new flatmates won’t change this split.</p>${receiptView(x)}<button class="btn" data-action="receipt" data-id="${esc(x.id)}">${x.receipt?'Replace receipt':'Attach receipt'}</button>`)}
function addTask(){if(!needMembers())return;openForm('Add weekly chore',field('Chore','title','text','','required maxlength="100" placeholder="e.g. Clean bathroom"')+notes('What needs doing?')+select('First assignment','member',options())+`<p class="inline-note">Starts in the week of ${fmtDate(week)} and repeats every week. Assignments rotate, or you can shuffle them.</p>`,f=>{const title=String(f.get('title')).trim();if(!title)throw Error('Add a chore name.');const t={id:id(),title,notes:f.get('notes'),starts:week};state.tasks.push(t);for(const [w,a]of Object.entries(state.weeks))if(w>=week)a[t.id]={member:f.get('member'),done:false};if(!state.weeks[week])state.weeks[week]={[t.id]:{member:f.get('member'),done:false}};toast('Weekly chore added.')},'Add chore')}
function addItem(){openForm('Add to the shopping list',field('What do we need?','title','text','','required maxlength="100" placeholder="Toilet paper"')+field('Quantity or details','quantity','text','','maxlength="40" placeholder="e.g. 12 pack"')+select('Added by','by',options('',true)).replace(' required',''),f=>{const title=String(f.get('title')).trim();if(!title)throw Error('Add an item name.');state.shopping.push({id:id(),title,quantity:f.get('quantity'),by:f.get('by'),done:false});toast('Added to the shopping list.')},'Add item')}
function addEvent(date=today()){openForm('Add flat event',field('Event title','title','text','','required maxlength="100" placeholder="e.g. Flat inspection"')+`<div class="fields">${field('Date','date','date',date,'required')}${field('Time optional','time','time')}</div>`+select('Type','type',['Flat event','Bill due','Inspection','Bin day','Dinner','Other'].map(x=>`<option>${x}</option>`).join(''))+notes(),f=>{const title=String(f.get('title')).trim();if(!title)throw Error('Add an event title.');state.events.push({id:id(),title,date:f.get('date'),time:f.get('time'),type:f.get('type'),notes:f.get('notes')});month=String(f.get('date')).slice(0,7);toast('Event added to the calendar.')},'Add event')}
function addFine(){if(!needMembers())return;openForm('Record an agreed fine',select('Flatmate','member',options())+field('Reason','reason','text','','required maxlength="100" placeholder="e.g. Left dishes for three days"')+`<div class="fields">${field('Amount NZD','amount','number','','required min="0.01" max="1000000" step="0.01"')}${field('Date','date','date',today(),'required')}</div>`+'<p class="inline-note">This goes into the flat fine register. It does not change expense balances or collect money.</p>',f=>{const reason=String(f.get('reason')).trim();if(!reason)throw Error('Add a reason.');state.fines.push({id:id(),member:f.get('member'),reason,amount:cents(f.get('amount')),date:f.get('date'),paid:false});toast('Fine recorded.')},'Record fine')}
function settings(){show('Your flat settings',`<form id="nameForm">${field('Flat name','name','text',state.name,'required maxlength="60"')}<button class="btn" type="submit">Save name</button></form><div class="settings-section"><h3>Flatmates</h3><div class="settings-members">${state.members.map(m=>`<span class="member-chip"><span class="round" style="width:23px;height:23px;font-size:9px">${esc(initial(m.id))}</span>${esc(m.name)}</span>`).join('')||'<p class="muted small">No flatmates added yet.</p>'}</div><form id="memberForm">${field('Add flatmate','member','text','','required maxlength="40" placeholder="Name"')}<p class="form-error" id="memberError" role="alert"></p><button class="btn" type="submit">＋ Add flatmate</button></form><p class="small muted">New flatmates join future expense splits. Existing expenses stay unchanged.</p></div><div class="settings-section"><h3>Keep a backup</h3><p class="small muted">This version saves only in this browser. Export and import manually to move data to another device. Import replaces the current flat.</p><div class="btn-row" style="margin-top:14px"><button class="btn" data-action="export">Export backup ↓</button><button class="btn" data-action="import">Import backup ↑</button></div></div>`);$('#nameForm').onsubmit=e=>{e.preventDefault();const name=String(new FormData(e.target).get('name')).trim();if(!name)return;state.name=name;save();render();toast('Flat name saved.')};$('#memberForm').onsubmit=e=>{e.preventDefault();const name=String(new FormData(e.target).get('member')).trim();if(!name)return;if(state.members.length>=20){$('#memberError').textContent='This version supports up to 20 flatmates.';return}if(state.members.some(m=>m.name.toLowerCase()===name.toLowerCase())){$('#memberError').textContent='Use a distinct name so balances stay clear.';return}const m={id:id(),name};state.members.push(m);for(const a of Object.values(state.weeks))for(const t of Object.values(a))if(t.member===null)t.member=m.id;save();render();settings();toast(name+' added to the flat.')}}
async function action(name,el){if(name==='reminder')return addReminder();if(name==='reminderDone'){const x=state.reminders.find(x=>x.id===el.dataset.id);if(x.repeat){x.date=dateAdd(x.date,x.repeat)}else x.done=!x.done;save();render();return}if(name==='reminderDelete'){state.reminders=state.reminders.filter(x=>x.id!==el.dataset.id);save();render();return}if(name==='reminderCalendar')return reminderCalendar(state.reminders.find(x=>x.id===el.dataset.id));if(name==='receipt'){const x=state.expenses.find(x=>x.id===el.dataset.id);return openForm('Expense receipt',receiptField(),async f=>{const receipt=await readReceipt(f.get('receipt'));if(!receipt)throw Error('Choose a receipt first.');x.receipt=receipt},'Save receipt')}if(name==='setup')return setup();if(name==='settings')return settings();if(name==='close')return close();if(name==='expense')return addExpense();if(name==='expenseDetail')return expenseDetail(state.expenses.find(x=>x.id===el.dataset.id));if(name==='task')return addTask();if(name==='item')return addItem();if(name==='event')return addEvent();if(name==='fine')return addFine();if(name==='prevWeek'||name==='nextWeek'){week=dateAdd(week,name==='prevWeek'?-7:7);return render()}if(name==='thisWeek'){week=monday(today());return render()}if(name==='prevMonth'||name==='nextMonth'){const d=dateObj(month+'-01');d.setUTCMonth(d.getUTCMonth()+(name==='prevMonth'?-1:1));month=d.toISOString().slice(0,7);return render()}if(name==='currentMonth'){month=today().slice(0,7);return render()}
 if(name==='shuffle'){const ts=tasksFor(week).filter(x=>!x.done),people=state.members.map(m=>m.id);for(let i=people.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[people[i],people[j]]=[people[j],people[i]]}let assign=ts.map((t,i)=>people[i%people.length]);if(people.length>1&&assign.every((p,i)=>p===ts[i].member))assign=assign.map(p=>people[(people.indexOf(p)+1)%people.length]);ts.forEach((t,i)=>state.weeks[week][t.id].member=assign[i]);save();render();toast('Unfinished chores reshuffled.');return}
 if(name==='assign'){const t=state.tasks.find(x=>x.id===el.dataset.id);openForm('Reassign '+t.title,select('Flatmate','member',options(state.weeks[week][t.id].member)),f=>{state.weeks[week][t.id].member=f.get('member');toast('Assignment updated.')});return}
 if(name==='settle'){const x={from:el.dataset.from,to:el.dataset.to,amount:Number(el.dataset.amount)};openForm('Record a repayment',`<p><strong>${esc(member(x.from))}</strong> paid <strong>${esc(member(x.to))}</strong> ${money(x.amount)}.</p>`+field('Payment date','date','date',today(),'required')+'<p class="inline-note">Only record this after the transfer has happened. This button does not send money.</p>',f=>{state.payments.push({...x,id:id(),date:f.get('date')});toast('Repayment recorded.')},'Confirm payment received');return}
 if(name==='day'){const d=el.dataset.date,events=state.events.filter(x=>x.date===d);if(!events.length)return addEvent(d);show(fmtDate(d,{weekday:'long',day:'numeric',month:'long'}),events.map(x=>`<div class="settlement"><div><h3>${esc(x.title)}</h3><p class="muted small">${x.time||'All day'} · ${esc(x.type)}</p><p class="notes small">${esc(x.notes)}</p></div></div>`).join('')+`<button class="btn primary" style="margin-top:20px" data-action="eventOnDate" data-date="${d}">＋ Add another event</button>`);return}
 if(name==='eventOnDate')return addEvent(el.dataset.date);if(name==='eventDetail'){const x=state.events.find(x=>x.id===el.dataset.id);show(x.title,`<p>${fmtDate(x.date,{weekday:'long',day:'numeric',month:'long'})} · ${x.time||'All day'}</p><p class="badge">${esc(x.type)}</p><p class="notes" style="margin-top:20px">${esc(x.notes||'No extra details.')}</p>`);return}
 if(name==='finePaid'){const f=state.fines.find(x=>x.id===el.dataset.id);f.paid=!f.paid;save();render();toast(f.paid?'Fine marked paid to the kitty.':'Fine marked unpaid.');return}
 if(name==='award'){if(!needMembers())return;const a=state.awards[week];openForm('Asshole of the Week',select('The flat’s chosen winner','member',options(a?.member))+field('The story','reason','text',a?.reason||'','required maxlength="200" placeholder="What earned them the crown?"')+`<p class="inline-note">Week of ${fmtDate(week)}. Record a decision the flat has agreed on. No fine is added automatically.</p>`,f=>{const reason=String(f.get('reason')).trim();if(!reason)throw Error('Add the reason for the award.');state.awards[week]={member:f.get('member'),reason};toast('The crown has been awarded.')},'Award the crown');return}
 if(name==='export'){const blob=new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='flatmate-hq-'+today()+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Flat backup exported.');return}if(name==='import'){$('#importFile').click();return}}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(el)action(el.dataset.action,el).catch(err=>toast(err.message))});document.addEventListener('change',e=>{const el=e.target;if(el.id==='activityFilter'){activityFilter=el.value;render();return}if(el.dataset.task){ensureWeek(el.dataset.week);state.weeks[el.dataset.week][el.dataset.task].done=el.checked;save();render()}if(el.dataset.item){state.shopping.find(x=>x.id===el.dataset.item).done=el.checked;save();render()}});$('#closeModal').onclick=close;$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=$('#modal').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});window.addEventListener('hashchange',()=>{render();window.scrollTo({top:0});$('#app').focus({preventScroll:true})});$('#importFile').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>8000000)throw Error('Choose a backup smaller than 8 MB.');const imported=validate(JSON.parse(await file.text()));show('Replace this flat with a backup?',`<p>Import <strong>${esc(imported.name)}</strong> with ${imported.members.length} flatmates and ${imported.expenses.length} expenses?</p><p class="muted small">This replaces the current browser data. Export your current flat first if you want to keep it.</p><div class="form-actions"><button class="btn" data-action="export">Export current flat</button><button class="btn primary" id="confirmImport">Replace and import</button></div>`);$('#confirmImport').onclick=()=>{state=imported;activityBefore=structuredClone(state);week=monday(today());month=today().slice(0,7);save();close();render();toast('Backup imported.')};}catch(err){toast('Import failed: '+err.message)}finally{e.target.value=''}};render();

function receiptField(){return '<label class="field">Receipt (optional)<input name="receipt" type="file" accept="image/jpeg,image/png,image/webp,application/pdf"></label><p class="small muted">Photo or PDF, up to 1 MB. Saved on this device and included in exported backups.</p>'}
async function readReceipt(file){if(!file||!file.size)return null;if(file.size>1000000)throw Error('Choose a receipt smaller than 1 MB.');if(!['image/jpeg','image/png','image/webp','application/pdf'].includes(file.type))throw Error('Choose a JPG, PNG, WebP or PDF receipt.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Receipt could not be read.'));reader.readAsDataURL(file)});const receipt={name:file.name.slice(0,200),data};if(!validReceipt(receipt))throw Error('Receipt could not be read.');return receipt}
function receiptView(x){if(!x.receipt)return '<p class="small muted">No receipt attached yet.</p>';return `<section class="receipt"><h3>Receipt</h3>${x.receipt.data.startsWith('data:image/')?`<img class="receipt-image" src="${x.receipt.data}" alt="Receipt for ${esc(x.title)}">`:''}<a class="btn" href="${x.receipt.data}" download="${esc(x.receipt.name)}">Download ${esc(x.receipt.name)}</a></section>`}
function reminderRows(items){return items.length?items.map(x=>`<div class="list-row"><span class="round">◷</span><div class="grow"><strong>${esc(x.title)}</strong><p>${fmtDate(x.date)} · ${esc(x.time)}${x.date<today()&&!x.done?' · Overdue':''} · ${x.repeat===7?'Weekly':x.repeat===14?'Fortnightly':'Once'}</p>${x.notes?`<p class="notes">${esc(x.notes)}</p>`:''}<div class="btn-row"><button class="text-link" data-action="reminderDone" data-id="${esc(x.id)}">${x.done?'Undo':x.repeat?'Done · next pickup':'Mark done'}</button><button class="text-link" data-action="reminderCalendar" data-id="${esc(x.id)}">Add to phone calendar</button><button class="text-link" data-action="reminderDelete" data-id="${esc(x.id)}">Remove</button></div></div></div>`).join(''):empty('No reminders yet','Add bin collection, rent, bills or anything the flat needs to remember.','reminder','Add reminder')}
function reminders(){return head('Remember the little things.','Set a date and time for bins, bills and household jobs.','reminder','Add reminder')+panel('Upcoming reminders',reminderRows(state.reminders.filter(x=>!x.done).sort((a,b)=>a.date.localeCompare(b.date)||a.time.localeCompare(b.time))))+`<p class="inline-note">Reminders are saved on this device. Use “Add to phone calendar” and import the downloaded calendar file for alerts when Flatmate HQ is closed. Each calendar reminder includes an alert one hour before.</p>`+(state.reminders.some(x=>x.done)?panel('Completed',reminderRows(state.reminders.filter(x=>x.done))):'')}
function addReminder(){openForm('Add reminder',field('What needs remembering?','title','text','','required maxlength="100" placeholder="e.g. Put rubbish bin out"')+`<div class="fields">${field('First date','date','date',today(),'required')}${field('Time','time','time','19:00','required')}</div>`+select('Repeat','repeat','<option value="0">Once</option><option value="7">Every week</option><option value="14">Every fortnight</option>')+notes()+ '<p class="inline-note">Choose when you want to do it, such as the evening before collection. Add it to your phone calendar after saving to receive alerts.</p>',f=>{const title=String(f.get('title')).trim();if(!title)throw Error('Add a reminder title.');state.reminders.push({id:id(),title,date:f.get('date'),time:f.get('time'),repeat:Number(f.get('repeat')),notes:f.get('notes'),done:false})},'Add reminder')}
function reminderCalendar(x){const clean=v=>String(v).replace(/\\/g,'\\\\').replace(/\n/g,'\\n').replace(/,/g,'\\,').replace(/;/g,'\\;').replace(/\r/g,'');const start=x.date.replace(/-/g,'')+'T'+x.time.replace(':','')+'00';const lines=['BEGIN:VCALENDAR','VERSION:2.0','PRODID:-//Flatmate HQ//Reminders//EN','BEGIN:VEVENT','UID:'+x.id+'@flatmate-hq','DTSTAMP:'+new Date().toISOString().replace(/[-:]/g,'').replace(/\.\d{3}/,''),'DTSTART;TZID=Pacific/Auckland:'+start,'SUMMARY:'+clean(x.title),'DESCRIPTION:'+clean(x.notes||'Flatmate HQ reminder')];if(x.repeat)lines.push('RRULE:FREQ=WEEKLY;INTERVAL='+(x.repeat/7));lines.push('BEGIN:VALARM','TRIGGER:-PT1H','ACTION:DISPLAY','DESCRIPTION:'+clean(x.title),'END:VALARM','END:VEVENT','END:VCALENDAR');const url=URL.createObjectURL(new Blob([lines.join('\r\n')+'\r\n'],{type:'text/calendar;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='flatmate-reminder.ics';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Open the downloaded calendar file to add your reminder.')}

function activityChanges(before,after){
 const out=[],at=new Date().toISOString(),push=(key,category,title,detail='')=>out.push({id:id(),key,category,title,detail,at});
 const configs={expenses:['expenses','Expense added'],payments:['expenses','Repayment recorded'],shopping:['shopping','Shopping item added'],tasks:['chores','Weekly chore added'],events:['calendar','Calendar event added'],reminders:['reminders','Reminder added'],fines:['fines','Fine recorded'],members:['flat','Flatmate added']};
 for(const [collection,[category,label]]of Object.entries(configs))for(const x of after[collection]){const old=before[collection].find(y=>y.id===x.id),key=collection+':'+x.id,title=x.title||x.reason||x.name||'';let detail=title;if(collection==='expenses')detail=member(x.payer)+' paid '+money(x.amount)+' · '+title;if(collection==='payments')detail=member(x.from)+' → '+member(x.to)+' · '+money(x.amount);if(collection==='fines')detail=member(x.member)+' · '+money(x.amount)+' · '+x.reason;if(!old){push(key,category,label,detail);continue}if(collection==='shopping'&&old.done!==x.done)push(key,category,x.done?'Shopping item bought':'Shopping item marked needed',title);if(collection==='expenses'&&JSON.stringify(old.receipt)!==JSON.stringify(x.receipt))push(key,category,'Receipt updated',title);if(collection==='fines'&&old.paid!==x.paid)push(key,category,x.paid?'Fine marked paid':'Fine marked unpaid',detail);if(collection==='reminders'&&(old.date!==x.date||old.done!==x.done))push(key,category,x.done?'Reminder completed':old.done?'Reminder reopened':'Reminder moved to next date',title+' · '+fmtDate(x.date));}
 for(const [w,assignments]of Object.entries(after.weeks))for(const [task,a]of Object.entries(assignments)){const old=before.weeks[w]?.[task];if(old&&old.done!==a.done){const t=after.tasks.find(t=>t.id===task);push('chore:'+w+':'+task,'chores',a.done?'Chore completed':'Chore reopened',(t?.title||'Chore')+' · '+member(a.member)+' · week of '+fmtDate(w));}}
 for(const [w,a]of Object.entries(after.awards))if(JSON.stringify(before.awards[w])!==JSON.stringify(a))push('award:'+w,'fines','Weekly crown awarded',member(a.member)+' · '+a.reason);
 return out;
}
function activityItems(){const logged=state.activity||[],known=new Set(logged.map(x=>x.key)),existing=[];for(const [collection,label]of [['expenses','Expense'],['payments','Repayment'],['fines','Fine']])for(const x of state[collection])if(!known.has(collection+':'+x.id))existing.push({id:x.id,key:collection+':'+x.id,category:collection==='fines'?'fines':'expenses',title:label,detail:collection==='payments'?member(x.from)+' → '+member(x.to)+' · '+money(x.amount):(x.title||x.reason)+' · '+money(x.amount),date:x.date,existing:true});return [...logged].reverse().concat(existing.sort((a,b)=>b.date.localeCompare(a.date)));}

function activityRows(items){return items.length?items.map(x=>`<div class="list-row activity-row"><span class="round">${x.category==='expenses'?'↔':x.category==='shopping'?'▤':x.category==='chores'?'✓':'◷'}</span><div class="grow"><strong>${esc(x.title)}</strong><p>${esc(x.detail)}</p><small class="muted">${x.existing?'Existing record · '+fmtDate(x.date):new Date(x.at).toLocaleString('en-NZ',{timeZone:'Pacific/Auckland',day:'numeric',month:'short',hour:'numeric',minute:'2-digit'})} · ${activityLabels[x.category]}</small></div><a class="text-link" href="#${x.category==='flat'?'home':x.category==='shopping'?'shopping':x.category==='calendar'?'calendar':x.category}">View ↗</a></div>`).join(''):empty('No activity here yet','Purchases, repayments and flat updates will appear as you use Flatmate HQ.');}
function activity(){const items=activityItems().filter(x=>activityFilter==='all'||x.category===activityFilter);return head('What’s been happening.','Recent purchases, expenses and the little things keeping your flat running.')+`<div class="week-bar"><label class="field">Show activity<select id="activityFilter"><option value="all">Everything</option>${Object.entries(activityLabels).map(([v,label])=>`<option value="${v}" ${activityFilter===v?'selected':''}>${label}</option>`).join('')}</select></label><span class="small muted">Newest updates first</span></div>`+panel('Flat activity',activityRows(items))+`<p class="inline-note">Activity is saved in this browser and included in backups. The latest 500 updates are kept. Existing expense records are shown below the updates; earlier shopping and chore changes weren’t recorded.</p>`;}
